/**
 * Built-in, original vector shape library (no third-party artwork).
 * All paths are authored for this project; some are generated by the small
 * helpers below. Output is deterministic (plain rounded numbers, no randomness).
 *
 * Shape ids are persisted in share links – never rename or reuse an id.
 */

export type ShapeCategory = 'basic' | 'action' | 'symbols' | 'frames'

export interface ShapeDef {
  /** kebab-case, stable. */
  id: string
  category: ShapeCategory
  /** Coordinate box of the path data. */
  width: number
  height: number
  /** SVG path data (M/L/C/Q/A/Z/H/V), filled. */
  d: string
  /** true for shapes with holes (frames, rings). */
  evenodd?: boolean
}

// ---------- tiny path helpers ----------

type Pt = [number, number]

const r2 = (n: number): number => {
  const v = Math.round(n * 100) / 100
  return v === 0 ? 0 : v
}
const P = (x: number, y: number): string => `${r2(x)} ${r2(y)}`

/** Closed polygon with straight edges. */
function poly(pts: Pt[]): string {
  return pts.map(([x, y], i) => `${i === 0 ? 'M' : 'L'}${P(x, y)}`).join('') + 'Z'
}

/** Closed polygon whose corners are rounded with quadratic curves (radius = cut distance). */
function roundedPoly(pts: Pt[], r: number): string {
  const n = pts.length
  let out = ''
  for (let i = 0; i < n; i++) {
    const v = pts[i]
    const a = pts[(i + n - 1) % n]
    const b = pts[(i + 1) % n]
    const d1 = Math.hypot(a[0] - v[0], a[1] - v[1])
    const d2 = Math.hypot(b[0] - v[0], b[1] - v[1])
    const t = Math.min(r, d1 / 2, d2 / 2)
    const p1: Pt = [v[0] + ((a[0] - v[0]) / d1) * t, v[1] + ((a[1] - v[1]) / d1) * t]
    const p2: Pt = [v[0] + ((b[0] - v[0]) / d2) * t, v[1] + ((b[1] - v[1]) / d2) * t]
    out += `${i === 0 ? 'M' : 'L'}${P(p1[0], p1[1])}Q${P(v[0], v[1])} ${P(p2[0], p2[1])}`
  }
  return out + 'Z'
}

/** Circle as two arcs (clockwise). */
function circle(cx: number, cy: number, r: number): string {
  return `M${P(cx - r, cy)}A${r2(r)} ${r2(r)} 0 0 1 ${P(cx + r, cy)}A${r2(r)} ${r2(r)} 0 0 1 ${P(cx - r, cy)}Z`
}

/** Rounded rectangle with circular corners. */
function roundRect(x: number, y: number, w: number, h: number, r: number): string {
  const k = r2(r)
  return (
    `M${P(x + r, y)}H${r2(x + w - r)}A${k} ${k} 0 0 1 ${P(x + w, y + r)}V${r2(y + h - r)}` +
    `A${k} ${k} 0 0 1 ${P(x + w - r, y + h)}H${r2(x + r)}A${k} ${k} 0 0 1 ${P(x, y + h - r)}` +
    `V${r2(y + r)}A${k} ${k} 0 0 1 ${P(x + r, y)}Z`
  )
}

function polar(cx: number, cy: number, r: number, deg: number): Pt {
  const a = (deg * Math.PI) / 180
  return [cx + Math.cos(a) * r, cy + Math.sin(a) * r]
}

/** Regular polygon, first vertex at angle `rot` degrees (-90 = pointing up). */
function regularPts(n: number, cx: number, cy: number, r: number, rot = -90): Pt[] {
  return Array.from({ length: n }, (_, i) => polar(cx, cy, r, rot + (360 / n) * i))
}

/** Star/burst points; `outer`/`inner` may be a number or a per-point cycle of radii. */
function starPts(n: number, cx: number, cy: number, outer: number | number[], inner: number | number[], rot = -90): Pt[] {
  const o = Array.isArray(outer) ? outer : [outer]
  const ii = Array.isArray(inner) ? inner : [inner]
  const pts: Pt[] = []
  for (let i = 0; i < n; i++) {
    pts.push(polar(cx, cy, o[i % o.length], rot + (360 / n) * i))
    pts.push(polar(cx, cy, ii[i % ii.length], rot + (360 / n) * (i + 0.5)))
  }
  return pts
}

type Op = ['M', number, number] | ['L', number, number] | ['C', number, number, number, number, number, number] | ['Q', number, number, number, number] | ['Z']

/** Serialise ops, mapping every coordinate pair through `tf`. */
function ops(list: Op[], tf: (x: number, y: number) => Pt = (x, y) => [x, y]): string {
  return list
    .map((op) => {
      if (op[0] === 'Z') return 'Z'
      const pairs: string[] = []
      for (let i = 1; i < op.length; i += 2) {
        const [x, y] = tf(op[i] as number, op[i + 1] as number)
        pairs.push(P(x, y))
      }
      return op[0] + pairs.join(' ')
    })
    .join('')
}

/** Uniform scale about a centre point. */
const scaleAbout = (k: number, cx: number, cy: number) => (x: number, y: number): Pt => [cx + (x - cx) * k, cy + (y - cy) * k]
const rotateAbout = (deg: number, cx: number, cy: number) => (x: number, y: number): Pt => {
  const a = (deg * Math.PI) / 180
  const dx = x - cx
  const dy = y - cy
  return [cx + dx * Math.cos(a) - dy * Math.sin(a), cy + dx * Math.sin(a) + dy * Math.cos(a)]
}

// ---------- generated shapes ----------

function gearPath(): string {
  const teeth = 10
  const step = 360 / teeth
  const rRoot = 36
  const rTip = 48
  let d = ''
  for (let i = 0; i < teeth; i++) {
    const a = -90 + step * i
    const p0 = polar(50, 50, rRoot, a - 11)
    const p1 = polar(50, 50, rTip, a - 7)
    const p2 = polar(50, 50, rTip, a + 7)
    const p3 = polar(50, 50, rRoot, a + 11)
    const next = polar(50, 50, rRoot, a + step - 11)
    d += `${i === 0 ? 'M' : 'L'}${P(p0[0], p0[1])}L${P(p1[0], p1[1])}L${P(p2[0], p2[1])}L${P(p3[0], p3[1])}`
    d += `A${rRoot} ${rRoot} 0 0 1 ${P(next[0], next[1])}`
  }
  return d + 'Z' + circle(50, 50, 15)
}

function swirlPath(): string {
  const outer: Pt[] = []
  const inner: Pt[] = []
  const steps = 110
  const tMax = 19.5
  for (let i = 0; i <= steps; i++) {
    const t = (tMax * i) / steps
    const rc = 4 + t * 2.05
    const w = 1.2 + t * 0.2
    const ang = (t - Math.PI / 2) // start pointing up
    outer.push(polar(50, 50, rc + w, (ang * 180) / Math.PI))
    inner.push(polar(50, 50, Math.max(0, rc - w), (ang * 180) / Math.PI))
  }
  const all = outer.concat(inner.reverse())
  return poly(all)
}

function speedFanPath(): string {
  // Tapered wedges radiating from a focus on the left.
  const fx = 6
  const fy = 50
  const rays: [number, number, number][] = [
    // angle, outer radius, half-angle
    [0, 92, 6],
    [-14, 86, 5],
    [14, 86, 5],
    [-27, 76, 5],
    [27, 76, 5],
    [-39, 62, 5],
    [39, 62, 5],
  ]
  return rays
    .map(([deg, r1, half]) => {
      const tip = polar(fx, fy, 12, deg)
      const a = polar(fx, fy, r1, deg - half)
      const b = polar(fx, fy, r1, deg + half)
      return poly([tip, a, b])
    })
    .join('')
}

function clawPath(): string {
  const claw = (dx: number, tipY: number) =>
    ops([
      ['M', 36 + dx, 3],
      ['L', 53 + dx, 3],
      ['Q', 49 + dx, 54, 2 + dx * 0.9 + 4, tipY],
      ['Q', 30 + dx, 52, 36 + dx, 3],
      ['Z'],
    ])
  return claw(0, 92) + claw(22, 97) + claw(44, 90)
}

function shockwavePath(): string {
  // Jagged outer ripple + smooth inner ripple (evenodd).
  const n = 28
  const pts: Pt[] = []
  for (let i = 0; i < n; i++) {
    pts.push(polar(50, 50, i % 2 === 0 ? 49 : 43, -90 + (360 / n) * i))
  }
  return poly(pts) + circle(50, 50, 37) + circle(50, 50, 30) + circle(50, 50, 15)
}

function pinwheelPath(): string {
  const blade: Op[] = [
    ['M', 50, 50],
    ['C', 43, 36, 49, 16, 76, 6],
    ['C', 66, 24, 66, 42, 50, 50],
    ['Z'],
  ]
  let d = ''
  for (let k = 0; k < 5; k++) d += ops(blade, rotateAbout(72 * k, 50, 50))
  return d
}

function wingsPath(): string {
  // Left wing as points; right wing is its mirror (x -> 120 - x).
  const left: Pt[] = [
    [2, 6], // leading tip
    [14, 22],
    [10, 30],
    [24, 36],
    [18, 46],
    [33, 49],
    [30, 59],
    [44, 58],
    [43, 68],
    [57, 62],
  ]
  const wing = (m: boolean): string => {
    const f = (p: Pt): Pt => (m ? [120 - p[0], p[1]] : p)
    const start = f([57, 26])
    const ctrl = f([32, 2])
    const first = f(left[0])
    let d = `M${P(start[0], start[1])}Q${P(ctrl[0], ctrl[1])} ${P(first[0], first[1])}`
    for (let i = 1; i < left.length; i++) {
      const p = f(left[i])
      d += `L${P(p[0], p[1])}`
    }
    return d + 'Z'
  }
  return wing(false) + wing(true)
}

function tornadoPath(): string {
  const bands: [number, number, number, number][] = [
    // cx, y, width, height
    [50, 3, 94, 14],
    [54, 21, 76, 14],
    [46, 39, 58, 14],
    [52, 57, 42, 13],
    [48, 74, 26, 12],
    [50, 89, 12, 9],
  ]
  return bands.map(([cx, y, w, h]) => roundRect(cx - w / 2, y, w, h, h / 2)).join('')
}

function cornersPath(): string {
  const t = 13
  const l = 36
  const tl: Pt[] = [
    [0, 0],
    [l, 0],
    [l, t],
    [t, t],
    [t, l],
    [0, l],
  ]
  const flip = (fx: number, fy: number): Pt[] => tl.map(([x, y]) => [fx ? 100 - x : x, fy ? 100 - y : y])
  return poly(flip(0, 0)) + poly(flip(1, 0)) + poly(flip(1, 1)) + poly(flip(0, 1))
}

function cutFrame(): string {
  const cut = (inset: number, c: number): Pt[] => [
    [inset + c, inset],
    [100 - inset - c, inset],
    [100 - inset, inset + c],
    [100 - inset, 100 - inset - c],
    [100 - inset - c, 100 - inset],
    [inset + c, 100 - inset],
    [inset, 100 - inset - c],
    [inset, inset + c],
  ]
  return poly(cut(2, 22)) + poly(cut(15, 14))
}

const SHIELD: Op[] = [
  ['M', 50, 3],
  ['C', 64, 13, 80, 15, 94, 15],
  ['L', 94, 50],
  ['C', 94, 76, 76, 92, 50, 99],
  ['C', 24, 92, 6, 76, 6, 50],
  ['L', 6, 15],
  ['C', 20, 15, 36, 13, 50, 3],
  ['Z'],
]

function skullPath(): string {
  const head =
    'M50 3C77 3 95 21 95 44C95 58 89 66 78 71L78 85Q78 95 68 95L32 95Q22 95 22 85L22 71C11 66 5 58 5 44C5 21 23 3 50 3Z'
  const nose = poly([
    [50, 58],
    [43, 72],
    [57, 72],
  ])
  const slots = [38.5, 47.5, 56.5].map((x) => roundRect(x, 80, 5, 10, 2.5)).join('')
  return head + circle(33, 47, 12) + circle(67, 47, 12) + nose + slots
}

